edges, writes it as JSON, and emits a Graphviz DOT visualization.

Node types:
    - "line":   a single speaker line (``Speaker: text -> Target``)
    - "choice": a numbered list of options (``1. text -> Target``)
"""

from __future__ import annotations

import json
import re
import sys
from collections import deque
from typing import Any


HEADER_RE = re.compile(r"^\[([^\]]+)\]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.*?)\s*->\s*(\S+)\s*$")
LINE_RE = re.compile(r"^\s*([^:]+):\s*(.*?)\s*->\s*(\S+)\s*$")


def parse_script(text: str) -> dict[str, list[dict[str, Any]]]:
    """Parse a dialogue script into a ``{"nodes": [...], "edges": [...]}`` dict."""
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, str]] = []
    seen_ids: set[str] = set()
    first_id: str | None = None

    def add_node(node: dict[str, Any]) -> None:
        if node["id"] in seen_ids:
            raise ValueError(f"Duplicate node id: {node['id']}")
        seen_ids.add(node["id"])
        nodes.append(node)

    def finalize(node_id: str, body: list[str]) -> None:
        body = [ln for ln in body if ln.strip()]
        if not body:
            # Empty block: treat as a line node with no outgoing edge.
            add_node({"id": node_id, "text": "", "speaker": "", "type": "line"})
            return

        is_choice = all(re.match(r"^\s*\d+\.\s", ln) for ln in body)

        if is_choice:
            add_node({"id": node_id, "text": "", "speaker": "", "type": "choice"})
            for ln in body:
                m = CHOICE_RE.match(ln)
                if not m:
                    raise ValueError(f"Malformed choice in [{node_id}]: {ln!r}")
                edges.append({"from": node_id, "to": m.group(2), "text": m.group(1)})
        else:
            if len(body) != 1:
                raise ValueError(
                    f"Line node [{node_id}] must contain exactly one speaker line"
                )
            m = LINE_RE.match(body[0])
            if not m:
                raise ValueError(f"Malformed line in [{node_id}]: {body[0]!r}")
            speaker, line_text, target = m.group(1).strip(), m.group(2).strip(), m.group(3)
            add_node(
                {"id": node_id, "text": line_text, "speaker": speaker, "type": "line"}
            )
            edges.append({"from": node_id, "to": target, "text": ""})

    current_id: str | None = None
    buffer: list[str] = []
    for raw in text.splitlines():
        header = HEADER_RE.match(raw.strip())
        if header:
            if current_id is not None:
                finalize(current_id, buffer)
            current_id = header.group(1).strip()
            if first_id is None:
                first_id = current_id
            buffer = []
        elif current_id is not None:
            buffer.append(raw)
    if current_id is not None:
        finalize(current_id, buffer)

    # Any edge target that was referenced but not defined (e.g. "End")
    # becomes a terminal node so every edge resolves to a real node.
    referenced = {e["to"] for e in edges}
    for ref in referenced:
        if ref not in seen_ids:
            add_node({"id": ref, "text": "", "speaker": "", "type": "line"})

    graph = {"nodes": nodes, "edges": edges}
    graph["_first"] = first_id  # internal, stripped before writing JSON
    return graph


def validate(graph: dict[str, Any]) -> None:
    """Check reachability from the first node and that edge targets exist."""
    nodes = graph["nodes"]
    edges = graph["edges"]
    first = graph.get("_first") or (nodes[0]["id"] if nodes else None)
    if first is None:
        raise ValueError("Graph has no nodes")

    ids = {n["id"] for n in nodes}

    # (2) All edge targets must exist (End is auto-added as a terminal node).
    for e in edges:
        if e["from"] not in ids:
            raise ValueError(f"Edge from unknown node: {e['from']}")
        if e["to"] not in ids:
            raise ValueError(f"Edge target does not exist: {e['to']}")

    # (1) All nodes reachable from the first node.
    adj: dict[str, list[str]] = {nid: [] for nid in ids}
    for e in edges:
        adj[e["from"]].append(e["to"])

    seen = {first}
    queue = deque([first])
    while queue:
        cur = queue.popleft()
        for nxt in adj[cur]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)

    unreachable = ids - seen
    if unreachable:
        raise ValueError(
            f"Unreachable nodes from '{first}': {sorted(unreachable)[:10]}"
            f" (total {len(unreachable)})"
        )


def to_dot(graph: dict[str, Any]) -> str:
    """Render the graph as a Graphviz DOT digraph."""

    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', '\\"')

    out = ["digraph Dialogue {", '    rankdir="LR";', '    node [shape=box, fontname="Helvetica"];']
    for n in graph["nodes"]:
        if n["type"] == "choice":
            label = f"{n['id']}\\n(choice)"
            shape = "diamond"
        else:
            body = f"{n['speaker']}: {n['text']}" if n["speaker"] else n["text"]
            label = f"{n['id']}\\n{body}" if body else n["id"]
            shape = "box"
        out.append(f'    "{esc(n["id"])}" [label="{esc(label)}", shape={shape}];')
    for e in graph["edges"]:
        if e["text"]:
            out.append(
                f'    "{esc(e["from"])}" -> "{esc(e["to"])}" [label="{esc(e["text"])}"];'
            )
        else:
            out.append(f'    "{esc(e["from"])}" -> "{esc(e["to"])}";')
    out.append("}")
    return "\n".join(out) + "\n"


def main(script_path: str, json_path: str, dot_path: str) -> None:
    with open(script_path, encoding="utf-8") as fh:
        text = fh.read()

    graph = parse_script(text)
    validate(graph)

    public = {"nodes": graph["nodes"], "edges": graph["edges"]}
    with open(json_path, "w", encoding="utf-8") as fh:
        json.dump(public, fh, indent=2, ensure_ascii=False)
    with open(dot_path, "w", encoding="utf-8") as fh:
        fh.write(to_dot(graph))

    print(f"Parsed {len(graph['nodes'])} nodes and {len(graph['edges'])} edges.")
    print(f"Wrote {json_path} and {dot_path}.")


if __name__ == "__main__":
    args = sys.argv[1:]
    script = args[0] if len(args) > 0 else "/app/script.txt"
    out_json = args[1] if len(args) > 1 else "/app/dialogue.json"
    out_dot = args[2] if len(args) > 2 else "/app/dialogue.dot"
    main(script, out_json, out_dot)
